            Assert.False(new object[] { 1, "2", 3 }.OfType<string>().Contains("4"));

            // Union
            Assert.True(new string[] { "a" }.Union(new string[] { "A" }).Contains("a"));
            Assert.True(new string[] { "a" }.Union(new string[] { "A" }).Contains("A"));
